{"path": "/tmp/sv-358b752ef0514b4cb59d99192df4d94e/Components/Board/AddTaskForm.razor", "file_text": "<div class="add-task-form">
    <div class="form-group">
        <label>Title</label>
        <input type="text" @bind="title" placeholder="Task title" />
    </div>
    <div class="form-group">
        <label>Assignee</label>
        <input type="text" @bind="assignee" placeholder="Assignee name" />
    </div>
    <div class="form-group">
        <label>Priority</label>
        <select @bind="priority">
            <option value="High">High</option>
            <option value="Medium">Medium</option>
            <option value="Low">Low</option>
        </select>
    </div>
    <div class="form-group">
        <label>Due Date</label>
        <input type="date" @bind="dueDate" />
    </div>
    <div class="form-actions">
        <button class="btn-save" @onclick="HandleSave" disabled="@IsSaving">
            @(IsSaving ? "Saving..." : "Save")
        </button>
        <button class="btn-cancel" @onclick="OnCancel" disabled="@IsSaving">Cancel</button>
    </div>
</div>

@code {
    [Parameter] public EventCallback<NewTaskData> OnSave { get; set; }
    [Parameter] public EventCallback OnCancel { get; set; }
    [Parameter] public bool IsSaving { get; set; }

    private string title = "";
    private string assignee = "";
    private string priority = "Medium";
    private DateTime dueDate = DateTime.Today.AddDays(7);

    private async Task HandleSave()
    {
        if (string.IsNullOrWhiteSpace(title)) return;
        await OnSave.InvokeAsync(new NewTaskData(title, assignee, priority, dueDate));
    }

    public record NewTaskData(string Title, string Assignee, string Priority, DateTime DueDate);
}
"}

