{"path": "/tmp/sv-358b752ef0514b4cb59d99192df4d94e/Components/Board/KanbanColumn.razor", "file_text": "<div class="kanban-column">
    <div class="column-header">
        <h3>@Title <span class="column-count">@Tasks.Count</span></h3>
    </div>
    <div class="column-body">
        @foreach (var task in Tasks)
        {
            <TaskCard Task="task"
                      CanMoveLeft="ColumnIndex > 0"
                      CanMoveRight="ColumnIndex < 2"
                      IsMoving="movingTaskId == task.Id"
                      OnMoveLeft="() => HandleMove(task.Id, -1)"
                      OnMoveRight="() => HandleMove(task.Id, 1)" />
        }
    </div>
    <div class="column-footer">
        @if (showForm)
        {
            <AddTaskForm OnSave="HandleSave"
                         OnCancel="() => showForm = false"
                         IsSaving="isSaving" />
        }
        else
        {
            <button class="btn-add" @onclick="() => showForm = true">+ Add Task</button>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired] public string Title { get; set; } = "";
    [Parameter, EditorRequired] public string Status { get; set; } = "";
    [Parameter, EditorRequired] public int ColumnIndex { get; set; }
    [Parameter] public List<TaskItem> Tasks { get; set; } = new();
    [Parameter] public EventCallback<(int TaskId, int Direction)> OnMoveTask { get; set; }
    [Parameter] public EventCallback<AddTaskForm.NewTaskData> OnAddTask { get; set; }

    private bool showForm;
    private bool isSaving;
    private int? movingTaskId;

    private async Task HandleMove(int taskId, int direction)
    {
        movingTaskId = taskId;
